from typing import List


def card_range_part3(BIN: str, info: List[List[str]]) -> List[List[str]]:
    width = len(BIN) + 10
    low, high = BIN + "0" * 10, BIN + "9" * 10
    # 起点升序；同起点时长的在前，保证外层区间先于被它包含的子区间
    ivs = sorted(([BIN + s.zfill(10), BIN + e.zfill(10), b] for s, e, b in info),
                 key=lambda x: (int(x[0]), -int(x[1])))
    outer, inner = [], []
    for iv in ivs:
        if outer and int(iv[1]) <= int(outer[-1][1]):
            inner.append(iv)            # 被上一个外层区间完全包含，原样保留
        else:
            outer.append(iv)
    if outer:
        outer[0][0] = low
        outer[-1][1] = high
        for i in range(len(outer) - 1):
            outer[i][1] = str(int(outer[i + 1][0]) - 1).zfill(width)
    return sorted(outer + inner, key=lambda x: (int(x[0]), -int(x[1])))

import java.util.*;
import java.math.BigInteger;

class Solution {
    public List<List<String>> cardRangePart3(String BIN, List<List<String>> info) {
        String low = BIN + "0000000000", high = BIN + "9999999999";
        List<List<String>> ivs = new ArrayList<>();
        for (List<String> iv : info) ivs.add(new ArrayList<>(List.of(BIN + iv.get(0), BIN + iv.get(1), iv.get(2))));
        ivs.sort((a, b) -> {
            int c = a.get(0).compareTo(b.get(0));
            if (c != 0) return c;
            return b.get(1).compareTo(a.get(1));
        });
        List<List<String>> outer = new ArrayList<>(), inner = new ArrayList<>();
        for (List<String> iv : ivs) {
            if (!outer.isEmpty() && iv.get(0).compareTo(outer.get(outer.size() - 1).get(0)) >= 0
                && iv.get(1).compareTo(outer.get(outer.size() - 1).get(1)) <= 0) inner.add(iv);
            else outer.add(iv);
        }
        if (!outer.isEmpty()) {
            outer.sort((a, b) -> a.get(0).compareTo(b.get(0)));
            outer.get(0).set(0, low);
            outer.get(outer.size() - 1).set(1, high);
            for (int i = 0; i + 1 < outer.size(); i++) {
                BigInteger nxt = new BigInteger(outer.get(i + 1).get(0)).subtract(BigInteger.ONE);
                String s = nxt.toString();
                while (s.length() < 16) s = "0" + s;
                outer.get(i).set(1, s);
            }
        }
        outer.addAll(inner);
        return outer;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
    string dec(string s) {
        int i = s.size() - 1;
        while (i >= 0 && s[i] == '0') { s[i] = '9'; i--; }
        if (i >= 0) s[i]--;
        return s;
    }
public:
    vector<vector<string>> cardRangePart3(string BIN, vector<vector<string>>& info) {
        string low = BIN + string(10, '0'), high = BIN + string(10, '9');
        vector<vector<string>> ivs;
        for (auto& iv : info) ivs.push_back({BIN + iv[0], BIN + iv[1], iv[2]});
        sort(ivs.begin(), ivs.end(), [](auto& a, auto& b) {
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] > b[1];
        });
        vector<vector<string>> outer, inner;
        for (auto& iv : ivs) {
            if (!outer.empty() && iv[0] >= outer.back()[0] && iv[1] <= outer.back()[1]) inner.push_back(iv);
            else outer.push_back(iv);
        }
        if (!outer.empty()) {
            sort(outer.begin(), outer.end());
            outer.front()[0] = low; outer.back()[1] = high;
            for (int i = 0; i + 1 < (int)outer.size(); i++) outer[i][1] = dec(outer[i + 1][0]);
        }
        for (auto& iv : inner) outer.push_back(iv);
        return outer;
    }
};
